#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────


# Verifies the cinema VMs built by infra/terraform against #33 and
# docs/infra/terraform.md, and writes a report to paste on #33.
#
#   verify-terraform.sh
#
# Runs on the admin workstation, on the tailnet, after `terraform apply`. It
# changes nothing: Terraform runs only fmt, validate and plan, and the network
# check starts a listener on db:5432 for 30 s only when nothing listens there.

TF_DIR="$(cd "$(dirname "$0")/../../infra/terraform" && pwd)"
REPORT="${REPORT:-terraform-verify-$(date +%F).md}"
RAW=$(mktemp)
SSH_CONFIG=$(mktemp)
trap 'rm -f "$RAW" "$SSH_CONFIG"' EXIT
RESULTS=()
FAILED=0

tf() { terraform -chdir="$TF_DIR" "$@"; }

# record PASS|FAIL "check" ["note"] adds one line to the result checklist.
record() {
  local mark="x"; [[ "$1" == PASS ]] || { mark=" "; FAILED=$((FAILED + 1)); }
  RESULTS+=("- [$mark] $2${3:+ — $3}")
  if [[ "$1" == PASS ]]; then printf '  %s✓ %s%s\n' "$GREEN" "$2" "$RESET"
  else printf '  %s✗ %s%s\n' "$RED" "$2${3:+ ($3)}" "$RESET"; fi
}

# check "name" CMD... records PASS when CMD succeeds.
check() {
  local name="$1"; shift
  if "$@"; then record PASS "$name"; else record FAIL "$name"; fi
}

# on VM 'COMMANDS' runs COMMANDS on cinema-<VM> through the ssh_config output.
on() { ssh -F "$SSH_CONFIG" "cinema-$1" "$2"; }

# raw "title" TEXT appends TEXT to the report's output section.
raw() { printf '== %s\n%s\n\n' "$1" "$2" >> "$RAW"; }

# write_report "title" writes the checklist and the raw output to $REPORT.
write_report() {
  {
    printf '## %s — %s\n\n' "$1" "$(date '+%F %H:%M')"
    printf 'Against #33 and `docs/infra/terraform.md`.\n\n'
    printf '%s\n' "${RESULTS[@]}"
    printf '\n<details><summary>Output</summary>\n\n```\n'
    cat "$RAW"
    printf '```\n\n</details>\n'
  } > "$REPORT"
}

TOTAL_STAGES=5
banner "Terraform VMs: verify (#33)"

stage "Before you start"
say "This checks proxy, app and db against #33. It changes nothing."
note "Terraform directory: $TF_DIR"
command -v terraform >/dev/null || { warn "terraform isn't installed."; exit 1; }
[[ -f "$TF_DIR/terraform.tfstate" ]] || { warn "No terraform.tfstate in $TF_DIR: run terraform apply first."; exit 1; }
tf output -raw ssh_config > "$SSH_CONFIG" || { warn "No ssh_config output: run terraform apply first."; exit 1; }
# The VMs are new and get rebuilt, so their host keys aren't pinned here.
cat >> "$SSH_CONFIG" <<'CFG'

Host cinema-*
  BatchMode yes
  ConnectTimeout 5
  StrictHostKeyChecking no
  UserKnownHostsFile /dev/null
  LogLevel ERROR
CFG
record PASS "Terraform state and ssh_config output found"
pause

stage "Terraform"
check "terraform fmt -check" tf fmt -check -recursive
check "terraform validate" tf validate -no-color
set +e
plan=$(tf plan -detailed-exitcode -input=false -lock=false -no-color 2>&1)
rc=$?
set -e
case $rc in
  0) record PASS "terraform plan shows no changes" ;;
  2) record FAIL "terraform plan shows no changes" "it plans changes" ;;
  *) record FAIL "terraform plan shows no changes" "plan failed" ;;
esac
raw "terraform plan" "$(tail -n 25 <<< "$plan")"
pause

stage "SSH"
say "Waiting for SSH and cloud-init on each VM (up to 5 min)…"
for vm in proxy app db; do
  got=""
  for _ in $(seq 60); do
    got=$(on "$vm" 'cloud-init status --wait >/dev/null 2>&1; echo "$(hostname) $(cloud-init status | sed "s/^status: //")"' 2>/dev/null) && break
    sleep 5
  done
  check "ssh cinema-$vm, cloud-init done" test "$got" = "$vm done"
  raw "cinema-$vm" "${got:-no answer}"
done
for vm in app db; do
  ip=$(tf output -json fixed_ips | python3 -c "import json,sys; print(json.load(sys.stdin)['$vm'])")
  check "Direct SSH to $vm ($ip) fails" \
    bash -c '! ssh -F /dev/null -o BatchMode=yes -o ConnectTimeout=5 "debian@$0" true 2>/dev/null' "$ip"
done
pause

stage "Docker, logs, SSH and updates"
for vm in proxy app db; do
  got=$(on "$vm" 'sudo docker info --format "{{.ServerVersion}} {{.LoggingDriver}}"; docker compose version --short' 2>/dev/null | tr '\n' ' ') || true
  check "$vm: docker info works, json-file logs, compose v2" bash -c '[[ "$0" =~ ^[0-9.]+\ json-file\ 2\. ]]' "$got"
  got=$(on "$vm" 'sudo cat /etc/docker/daemon.json; sudo systemd-analyze cat-config systemd/journald.conf | grep -E "^SystemMaxUse="; sudo sshd -T | grep -E "^(passwordauthentication|kbdinteractiveauthentication|permitrootlogin) "; apt-config dump | grep -E "Origins-Pattern::|Automatic-Reboot "' 2>/dev/null) || true
  raw "$vm settings" "$got"
  check "$vm: Docker logs capped at 10m × 3" bash -c '[[ "$0" == *\"10m\"* && "$0" == *\"3\"* ]]' "$got"
  check "$vm: journald SystemMaxUse=100M" bash -c '[[ "$0" == *SystemMaxUse=100M* ]]' "$got"
  check "$vm: SSH keys only, no root login" \
    bash -c '[[ "$0" == *"passwordauthentication no"* && "$0" == *"kbdinteractiveauthentication no"* && "$0" == *"permitrootlogin no"* ]]' "$got"
  check "$vm: unattended-upgrades: Debian security and Docker only, no reboot" \
    bash -c '[[ $(grep -c "Origins-Pattern::" <<< "$0") == 2 && "$0" == *Debian-Security* && "$0" == *"Docker CE"* && "$0" == *"Automatic-Reboot \"false\""* ]]' "$got"
done
got=$(on db 'findmnt -no SOURCE,FSTYPE,LABEL /srv/pgdata; grep " /srv/pgdata " /etc/fstab' 2>/dev/null) || true
raw "db /srv/pgdata" "$got"
check "db: pgdata volume mounted at /srv/pgdata" bash -c '[[ "$0" == *ext4\ pgdata* && "$0" == *LABEL=pgdata* ]]' "$got"
pause

stage "Network: who reaches db:5432"
say "From app, db:5432 must connect. From proxy, it must time out: the security"
say "group drops the packets."
listener=""
if ! on db 'sudo ss -Hltn "sport = :5432" | grep -q .' 2>/dev/null; then
  note "Nothing listens on db:5432 yet: starting nc -l for 30 s."
  on db 'nohup timeout 30 nc -lk 5432 </dev/null >/dev/null 2>&1 &' && listener=1
  sleep 1
fi
check "app → db:5432 connects" on app 'nc -zw3 db 5432'
start=$(date +%s)
if on proxy 'nc -zw3 db 5432' 2>/dev/null; then
  record FAIL "proxy → db:5432 times out" "it connected"
else
  secs=$(( $(date +%s) - start ))
  if (( secs >= 3 )); then record PASS "proxy → db:5432 times out" "${secs}s"
  else record FAIL "proxy → db:5432 times out" "failed after ${secs}s, refused instead of dropped?"; fi
fi
check "proxy → app:22 connects" on proxy 'nc -zw3 app 22'
raw "/etc/hosts on app" "$(on app 'grep -E " (proxy|app|db)$" /etc/hosts' 2>/dev/null)"
[[ -n "$listener" ]] && on db 'pkill -f "nc -lk 5432"' 2>/dev/null || true
pause

write_report "Terraform VMs verification"
finish
if (( FAILED )); then warn "$FAILED check(s) failed; see $REPORT"
else note "All checks passed."; fi
note "Paste $REPORT as a comment on issue #33."
printf '\n'
